#!/bin/sh
# Generated by `codeyam-editor editor devcontainer-setup`. Runs each time
# this codespace's window connects (postAttachCommand): waits for the
# CodeYam Editor, starts it if nothing is running it, then prints the link
# to open it — or, if it cannot start, why and what to run.

port=14199
url="https://$CODESPACE_NAME-$port.$GITHUB_CODESPACES_PORT_FORWARDING_DOMAIN"
rule='=================================================='
log=.codeyam/logs/codespaces-editor.log
record=.codeyam/run/codespaces-launch.json

field() {
  sed -n "s/.*\"$1\":\"\{0,1\}\([^,\"}]*\).*/\1/p" "$record" 2>/dev/null
}
alive() { [ -n "$1" ] && [ "$1" != null ] && kill -0 "$1" 2>/dev/null; }

# What is happening now, for the progress line; empty when nothing is.
phase() {
  if pgrep -f codeyam-system-deps.sh > /dev/null 2>&1; then
    echo 'installing system packages'
  elif ! command -v codeyam-editor > /dev/null 2>&1; then
    echo 'installing the CodeYam Editor'
  elif alive "$(field pid)" || pgrep -f codeyam-editor > /dev/null 2>&1; then
    echo "editor running, waiting for port $port"
  elif alive "$(field supervisor)"; then
    echo "editor starting (attempt $(field attempt))"
  fi
}

fail() {
  printf '\n%s\n  The CodeYam Editor did not start: %s.\n' "$rule" "$1"
  code=$(field exitCode); sig=$(field signal)
  if [ -n "$sig" ] && [ "$sig" != null ]; then
    echo "  Its last attempt was killed by signal $sig."
  elif [ -n "$code" ] && [ "$code" != null ]; then
    echo "  Its last attempt exited with code $code."
  fi
  # The editor's own lines from its last attempt (the launcher's start with ---).
  said=$(awk '/^--- launch attempt /{s=""; next} !/^--- /{s=s $0 "\n"} END{printf "%s", s}' "$log" 2>/dev/null)
  if [ -z "$said" ]; then
    echo "  The editor's log is empty — it exited before printing anything."
  fi
  if [ -s "$log" ]; then
    printf '\n  The end of %s:\n\n' "$log"
    tail -n 15 "$log" | sed 's/^/    /'
  fi
  printf '\n  To start it again, run:\n\n    sh .devcontainer/codeyam-start.sh attach\n\n'
  printf '  or run it in this terminal to watch it start:\n\n    codeyam-editor start --hosted --no-open --port 14199\n\n'
  printf '  Full log: cat %s\n%s\n\n' "$log" "$rule"
  exit 0
}

echo 'Waiting for the CodeYam Editor to start...'
started=$(date +%s)
i=0
idle=0
relaunched=0
until curl -s -o /dev/null --max-time 2 "http://127.0.0.1:$port/"; do
  i=$((i + 1))
  [ "$(field state)" = gave-up ] && fail "it was started $(field attempt) times and stopped each time"
  now=$(phase)
  if [ -n "$now" ]; then
    idle=0
  else
    idle=$((idle + 1))
  fi
  # Nothing is running or starting the editor: start it, once.
  if [ "$idle" -ge 5 ]; then
    if [ "$relaunched" = 1 ]; then
      fail 'it was started again and stopped'
    fi
    echo 'The CodeYam Editor is not running — starting it now.'
    mkdir -p "$(dirname "$log")"
    setsid -f nohup sh .devcontainer/codeyam-start.sh attach >> .codeyam/logs/codespaces-editor.log 2>&1 < /dev/null
    relaunched=1
    idle=0
  fi
  [ "$i" -ge 300 ] && fail 'it did not answer in time'
  if [ $((i % 7)) -eq 0 ]; then
    echo "[$(($(date +%s) - started))s] ${now:-waiting}..."
  fi
  sleep 2
done

printf '\n%s\n  CodeYam Editor is ready. Open it here (Cmd/Ctrl+click):\n\n  %s\n%s\n\n' \
  "$rule" "$url" "$rule"

# Opens a tab on its own once pop-ups are allowed for this site.
if [ -n "${BROWSER:-}" ]; then
  "$BROWSER" "$url" > /dev/null 2>&1
fi

# Keep this codespace awake while the editor is busy.
pkill -f codeyam-keepalive.sh 2>/dev/null
exec sh .devcontainer/codeyam-keepalive.sh
